-- Adhunik ERP - Phase 5A Proforma Invoices
begin;
alter table public.numbering_configurations drop constraint if exists numbering_configurations_entity_type_check;
alter table public.numbering_configurations add constraint numbering_configurations_entity_type_check check(entity_type in('EMPLOYEE','CUSTOMER','INQUIRY','ORDER','PROFORMA_INVOICE'));
insert into public.numbering_configurations(entity_type,prefix,padding,separator,include_financial_year) values('PROFORMA_INVOICE','PI',4,'-',true) on conflict(entity_type) do nothing;
create table if not exists public.proforma_invoices(
 id uuid primary key default gen_random_uuid(),pi_number text not null unique,order_id uuid not null references public.orders(id) on delete restrict,company_id uuid not null references public.customer_companies(id) on delete restrict,contact_id uuid references public.customer_contacts(id) on delete restrict,
 pi_date date not null default current_date,our_reference_number text,dp_code text,project_name text,customer_po_number text,customer_po_date date,
 billing_address_id uuid references public.customer_addresses(id) on delete restrict,shipping_address_id uuid references public.customer_addresses(id) on delete restrict,billing_address_snapshot jsonb not null,shipping_address_snapshot jsonb not null,
 customer_name_snapshot text not null,customer_gstin_snapshot text,customer_phone_snapshot text,customer_email_snapshot text,payment_term_id uuid references public.payment_terms(id) on delete restrict,payment_terms_snapshot text,delivery_terms text,validity_text text,
 freight_amount numeric(18,2) not null default 0 check(freight_amount>=0),freight_remark text,gst_percentage numeric(7,4) not null default 0 check(gst_percentage between 0 and 100),subtotal numeric(18,2) not null default 0 check(subtotal>=0),discount_total numeric(18,2) not null default 0 check(discount_total>=0),taxable_total numeric(18,2) not null default 0 check(taxable_total>=0),gst_amount numeric(18,2) not null default 0 check(gst_amount>=0),grand_total numeric(18,2) not null default 0 check(grand_total>=0),currency varchar(3) not null default 'INR',status text not null default 'DRAFT' check(status in('DRAFT','CANCELLED')),
 salesperson_id uuid not null references auth.users(id) on delete restrict,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now(),cancelled_at timestamptz,cancelled_by uuid references auth.users(id) on delete restrict,cancellation_reason text,deleted_at timestamptz,deleted_by uuid references auth.users(id) on delete set null,
 constraint pi_cancellation_details check((status='CANCELLED' and cancellation_reason is not null and cancelled_at is not null and cancelled_by is not null)or(status<>'CANCELLED' and cancellation_reason is null and cancelled_at is null and cancelled_by is null))
);
create table if not exists public.proforma_invoice_items(id uuid primary key default gen_random_uuid(),proforma_invoice_id uuid not null references public.proforma_invoices(id) on delete cascade,line_number integer not null check(line_number>0),inventory_item_id uuid,item_name text,item_description text not null,model_type text,hsn_code text,unit text not null,quantity numeric(18,4) not null check(quantity>0),unit_price numeric(18,4) not null check(unit_price>=0),discount_percentage numeric(7,4) not null default 0 check(discount_percentage between 0 and 100),gross_amount numeric(18,2) not null check(gross_amount>=0),discount_amount numeric(18,2) not null check(discount_amount>=0),line_total numeric(18,2) not null check(line_total>=0),sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(proforma_invoice_id,line_number));
create table if not exists public.proforma_invoice_activities(id uuid primary key default gen_random_uuid(),proforma_invoice_id uuid not null references public.proforma_invoices(id) on delete restrict,activity_type text not null check(activity_type in('CREATED','EDITED','ITEM_ADDED','ITEM_REMOVED','STATUS_CHANGED','CANCELLED')),description text not null,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now());
insert into public.numbering_counters(entity_type,current_value) select 'PROFORMA_INVOICE',coalesce(max((substring(pi_number from '([0-9]+)$'))::bigint),0) from public.proforma_invoices where pi_number~'[0-9]+$' on conflict(entity_type) do update set current_value=greatest(public.numbering_counters.current_value,excluded.current_value);
create unique index if not exists proforma_invoices_one_draft_per_order on public.proforma_invoices(order_id) where status='DRAFT' and deleted_at is null;
create index if not exists proforma_invoices_order on public.proforma_invoices(order_id,created_at desc) where deleted_at is null;create index if not exists proforma_invoices_company on public.proforma_invoices(company_id,pi_date desc) where deleted_at is null;create index if not exists proforma_invoices_contact on public.proforma_invoices(contact_id) where contact_id is not null and deleted_at is null;create index if not exists proforma_invoices_salesperson on public.proforma_invoices(salesperson_id,status) where deleted_at is null;create index if not exists proforma_invoices_status_date on public.proforma_invoices(status,pi_date desc) where deleted_at is null;create index if not exists proforma_invoices_po on public.proforma_invoices(customer_po_number) where customer_po_number is not null and deleted_at is null;create index if not exists proforma_invoice_items_parent on public.proforma_invoice_items(proforma_invoice_id,sort_order,line_number);create index if not exists proforma_invoice_activities_parent on public.proforma_invoice_activities(proforma_invoice_id,created_at desc);
create or replace function public.can_view_proforma_invoice(p_pi_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.proforma_invoices p where p.id=p_pi_id and p.deleted_at is null and(public.current_erp_role()='ADMIN' or p.created_by=auth.uid() or p.salesperson_id=auth.uid() or public.can_view_order(p.order_id)))$$;
create or replace function public.can_manage_proforma_invoice(p_pi_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.proforma_invoices p where p.id=p_pi_id and p.deleted_at is null and p.status='DRAFT' and(public.can_manage_crm() or p.created_by=auth.uid() or p.salesperson_id=auth.uid()))$$;
create or replace function public.save_proforma_invoice(p_pi_id uuid,p_order_id uuid,p_data jsonb,p_items jsonb)returns uuid language plpgsql security definer set search_path='' as $$
declare o public.orders%rowtype;c public.customer_companies%rowtype;ct public.customer_contacts%rowtype;b public.customer_addresses%rowtype;s public.customer_addresses%rowtype;t public.payment_terms%rowtype;v_id uuid;v_ct uuid;v_b uuid;v_s uuid;v_t uuid;v_sales uuid;v_line jsonb;v_n int:=0;v_old int:=0;v_qty numeric;v_rate numeric;v_pct numeric;v_gross numeric;v_disc numeric;v_net numeric;v_sub numeric:=0;v_discs numeric:=0;v_gst numeric;v_freight numeric;v_currency text;
begin
 if not public.has_active_erp_access()then raise exception 'Active ERP access is required';end if;if jsonb_typeof(p_items)<>'array'or jsonb_array_length(p_items)=0 then raise exception 'Add at least one PI item';end if;
 if p_pi_id is null then select * into o from public.orders where id=p_order_id and deleted_at is null and status<>'CANCELLED' for update;if not found or not public.can_view_order(p_order_id)then raise exception 'Order not found or not accessible';end if;if exists(select 1 from public.proforma_invoices where order_id=o.id and status='DRAFT' and deleted_at is null)then raise exception 'A Draft PI already exists for this Order';end if;
 else select p.order_id into p_order_id from public.proforma_invoices p where p.id=p_pi_id and public.can_manage_proforma_invoice(p.id) for update;if not found then raise exception 'Draft PI not found or not editable';end if;select * into o from public.orders where id=p_order_id;v_id:=p_pi_id;select count(*) into v_old from public.proforma_invoice_items where proforma_invoice_id=v_id;end if;
 select * into c from public.customer_companies where id=o.company_id and deleted_at is null;if not found then raise exception 'Order customer is unavailable';end if;
 v_ct:=nullif(p_data->>'contact_id','')::uuid;if v_ct is not null then select * into ct from public.customer_contacts where id=v_ct and customer_company_id=o.company_id and deleted_at is null and is_active;if not found then raise exception 'Select a valid customer contact';end if;end if;
 v_b:=nullif(p_data->>'billing_address_id','')::uuid;v_s:=nullif(p_data->>'shipping_address_id','')::uuid;select * into b from public.customer_addresses where id=v_b and customer_company_id=o.company_id and deleted_at is null;if not found then raise exception 'Select a valid billing address';end if;select * into s from public.customer_addresses where id=v_s and customer_company_id=o.company_id and deleted_at is null;if not found then raise exception 'Select a valid shipping address';end if;
 v_t:=nullif(p_data->>'payment_term_id','')::uuid;if v_t is not null then select * into t from public.payment_terms where id=v_t and deleted_at is null and is_active;if not found then raise exception 'Select a valid payment term';end if;end if;
 v_sales:=coalesce(nullif(p_data->>'salesperson_id','')::uuid,o.salesperson_id);if v_sales<>o.salesperson_id and not public.can_manage_crm()then raise exception 'Only Admin or Manager can reassign the salesperson';end if;if not exists(select 1 from public.erp_profiles where auth_user_id=v_sales and is_active)then raise exception 'Salesperson must have active ERP access';end if;
 v_gst:=coalesce(nullif(p_data->>'gst_percentage','')::numeric,0);v_freight:=coalesce(nullif(p_data->>'freight_amount','')::numeric,0);if v_gst<0 or v_gst>100 then raise exception 'GST percentage must be between 0 and 100';end if;if v_freight<0 then raise exception 'Freight cannot be negative';end if;
 for v_line in select value from jsonb_array_elements(p_items)loop v_n:=v_n+1;v_qty:=nullif(v_line->>'quantity','')::numeric;v_rate:=nullif(v_line->>'unit_price','')::numeric;v_pct:=coalesce(nullif(v_line->>'discount_percentage','')::numeric,0);if nullif(trim(v_line->>'item_description'),'')is null or nullif(trim(v_line->>'unit'),'')is null then raise exception 'Item % requires description and unit',v_n;end if;if v_qty is null or v_qty<=0 or v_rate is null or v_rate<0 or v_pct<0 or v_pct>100 then raise exception 'Item % has invalid quantity, price or discount',v_n;end if;v_gross:=round(v_qty*v_rate,2);v_disc:=round(v_gross*v_pct/100,2);v_net:=round(v_gross-v_disc,2);v_sub:=v_sub+v_net;v_discs:=v_discs+v_disc;end loop;
 v_currency:=upper(coalesce(nullif(p_data->>'currency',''),(select value from public.system_settings where category='LOCALIZATION' and key='DEFAULT_CURRENCY'),'INR'));if v_currency!~'^[A-Z]{3}$'then raise exception 'Currency must be a 3-letter code';end if;
 if v_id is null then insert into public.proforma_invoices(pi_number,order_id,company_id,contact_id,pi_date,our_reference_number,dp_code,project_name,customer_po_number,customer_po_date,billing_address_id,shipping_address_id,billing_address_snapshot,shipping_address_snapshot,customer_name_snapshot,customer_gstin_snapshot,customer_phone_snapshot,customer_email_snapshot,payment_term_id,payment_terms_snapshot,delivery_terms,validity_text,freight_amount,freight_remark,gst_percentage,subtotal,discount_total,taxable_total,gst_amount,grand_total,currency,salesperson_id,created_by,updated_by)values(public.allocate_business_number('PROFORMA_INVOICE'),o.id,o.company_id,v_ct,coalesce(nullif(p_data->>'pi_date','')::date,current_date),nullif(p_data->>'our_reference_number',''),nullif(p_data->>'dp_code',''),nullif(p_data->>'project_name',''),nullif(p_data->>'customer_po_number',''),nullif(p_data->>'customer_po_date','')::date,b.id,s.id,to_jsonb(b)-'created_by'-'updated_by'-'deleted_by',to_jsonb(s)-'created_by'-'updated_by'-'deleted_by',coalesce(nullif(p_data->>'customer_name',''),c.legal_name),coalesce(nullif(p_data->>'customer_gstin',''),c.gstin),coalesce(nullif(p_data->>'customer_phone',''),ct.phone,c.primary_phone),coalesce(nullif(p_data->>'customer_email',''),ct.email,c.primary_email),v_t,case when v_t is null then null else coalesce(nullif(p_data->>'payment_terms',''),t.name)end,nullif(p_data->>'delivery_terms',''),nullif(p_data->>'validity_text',''),round(v_freight,2),nullif(p_data->>'freight_remark',''),v_gst,round(v_sub,2),round(v_discs,2),round(v_sub,2),round(v_sub*v_gst/100,2),round(v_sub+round(v_sub*v_gst/100,2)+v_freight,2),v_currency,v_sales,auth.uid(),auth.uid())returning id into v_id;insert into public.proforma_invoice_activities(proforma_invoice_id,activity_type,description,created_by)values(v_id,'CREATED','Draft PI created from Order '||o.order_number,auth.uid());
 else update public.proforma_invoices set contact_id=v_ct,pi_date=coalesce(nullif(p_data->>'pi_date','')::date,pi_date),our_reference_number=nullif(p_data->>'our_reference_number',''),dp_code=nullif(p_data->>'dp_code',''),project_name=nullif(p_data->>'project_name',''),customer_po_number=nullif(p_data->>'customer_po_number',''),customer_po_date=nullif(p_data->>'customer_po_date','')::date,billing_address_id=b.id,shipping_address_id=s.id,billing_address_snapshot=to_jsonb(b)-'created_by'-'updated_by'-'deleted_by',shipping_address_snapshot=to_jsonb(s)-'created_by'-'updated_by'-'deleted_by',customer_name_snapshot=coalesce(nullif(p_data->>'customer_name',''),customer_name_snapshot),customer_gstin_snapshot=nullif(p_data->>'customer_gstin',''),customer_phone_snapshot=nullif(p_data->>'customer_phone',''),customer_email_snapshot=nullif(p_data->>'customer_email',''),payment_term_id=v_t,payment_terms_snapshot=nullif(p_data->>'payment_terms',''),delivery_terms=nullif(p_data->>'delivery_terms',''),validity_text=nullif(p_data->>'validity_text',''),freight_amount=round(v_freight,2),freight_remark=nullif(p_data->>'freight_remark',''),gst_percentage=v_gst,subtotal=round(v_sub,2),discount_total=round(v_discs,2),taxable_total=round(v_sub,2),gst_amount=round(v_sub*v_gst/100,2),grand_total=round(v_sub+round(v_sub*v_gst/100,2)+v_freight,2),currency=v_currency,salesperson_id=v_sales,updated_by=auth.uid(),updated_at=now()where id=v_id;delete from public.proforma_invoice_items where proforma_invoice_id=v_id;insert into public.proforma_invoice_activities(proforma_invoice_id,activity_type,description,created_by)values(v_id,'EDITED','Draft PI edited',auth.uid());end if;
 v_n:=0;for v_line in select value from jsonb_array_elements(p_items)loop v_n:=v_n+1;v_qty:=(v_line->>'quantity')::numeric;v_rate:=(v_line->>'unit_price')::numeric;v_pct:=coalesce(nullif(v_line->>'discount_percentage','')::numeric,0);v_gross:=round(v_qty*v_rate,2);v_disc:=round(v_gross*v_pct/100,2);insert into public.proforma_invoice_items(proforma_invoice_id,line_number,inventory_item_id,item_name,item_description,model_type,hsn_code,unit,quantity,unit_price,discount_percentage,gross_amount,discount_amount,line_total,sort_order)values(v_id,v_n,nullif(v_line->>'inventory_item_id','')::uuid,nullif(v_line->>'item_name',''),trim(v_line->>'item_description'),nullif(v_line->>'model_type',''),nullif(v_line->>'hsn_code',''),trim(v_line->>'unit'),v_qty,v_rate,v_pct,v_gross,v_disc,round(v_gross-v_disc,2),v_n);end loop;
 if p_pi_id is not null and v_old<jsonb_array_length(p_items)then insert into public.proforma_invoice_activities(proforma_invoice_id,activity_type,description,created_by)values(v_id,'ITEM_ADDED','PI item added',auth.uid());elsif p_pi_id is not null and v_old>jsonb_array_length(p_items)then insert into public.proforma_invoice_activities(proforma_invoice_id,activity_type,description,created_by)values(v_id,'ITEM_REMOVED','PI item removed',auth.uid());end if;return v_id;
exception when unique_violation then raise exception 'A Draft PI already exists for this Order or PI number conflicts';end;$$;
create or replace function public.cancel_proforma_invoice(p_pi_id uuid,p_reason text)returns void language plpgsql security definer set search_path='' as $$begin if nullif(trim(p_reason),'')is null then raise exception 'Cancellation reason is required';end if;update public.proforma_invoices set status='CANCELLED',cancellation_reason=trim(p_reason),cancelled_at=now(),cancelled_by=auth.uid(),updated_by=auth.uid(),updated_at=now()where id=p_pi_id and public.can_manage_proforma_invoice(id);if not found then raise exception 'Draft PI not found or not cancellable';end if;insert into public.proforma_invoice_activities(proforma_invoice_id,activity_type,description,created_by)values(p_pi_id,'CANCELLED','PI cancelled: '||trim(p_reason),auth.uid());end;$$;
create or replace function public.protect_proforma_invoice()returns trigger language plpgsql security definer set search_path='' as $$begin new.pi_number:=old.pi_number;new.order_id:=old.order_id;new.company_id:=old.company_id;new.created_by:=old.created_by;new.created_at:=old.created_at;if old.status='CANCELLED'then raise exception 'Cancelled PI cannot be edited';end if;return new;end;$$;
drop trigger if exists protect_proforma_invoice on public.proforma_invoices;create trigger protect_proforma_invoice before update on public.proforma_invoices for each row execute function public.protect_proforma_invoice();drop trigger if exists set_pi_items_updated_at on public.proforma_invoice_items;create trigger set_pi_items_updated_at before update on public.proforma_invoice_items for each row execute function public.set_updated_at();
alter table public.proforma_invoices enable row level security;alter table public.proforma_invoice_items enable row level security;alter table public.proforma_invoice_activities enable row level security;drop policy if exists "Sales visible PIs" on public.proforma_invoices;drop policy if exists "Sales visible PI items" on public.proforma_invoice_items;drop policy if exists "Sales visible PI activities" on public.proforma_invoice_activities;create policy "Sales visible PIs" on public.proforma_invoices for select to authenticated using(public.can_view_proforma_invoice(id));create policy "Sales visible PI items" on public.proforma_invoice_items for select to authenticated using(public.can_view_proforma_invoice(proforma_invoice_id));create policy "Sales visible PI activities" on public.proforma_invoice_activities for select to authenticated using(public.can_view_proforma_invoice(proforma_invoice_id));grant select on public.proforma_invoices,public.proforma_invoice_items,public.proforma_invoice_activities to authenticated;revoke all on function public.save_proforma_invoice(uuid,uuid,jsonb,jsonb),public.cancel_proforma_invoice(uuid,text)from public,anon;grant execute on function public.can_view_proforma_invoice(uuid),public.can_manage_proforma_invoice(uuid),public.save_proforma_invoice(uuid,uuid,jsonb,jsonb),public.cancel_proforma_invoice(uuid,text)to authenticated;
commit;

